// Sundown held packs whose tokens now match a founder lock.
// Panels are the NIH DSLD on-market label records from t238u.
// The 3+ Limited note is stored only where the stack is still 3+.

import type { IngredientFlag, RatingRecord } from '../ratingRecord';
import { T240U_STACK_NOTE } from '../scan-preview/t240uLocks';

const UNVERIFIED = 'unverified' as const;
const SUPPLEMENT = 'Supplement' as const;

function flag(panel: string, name: string, grade: IngredientFlag['riskLevel'], counts: boolean, why?: string): IngredientFlag {
  const meth = why && why.startsWith('Methodology')
    ? why
    : grade === 'limited'
      ? 'Methodology §5 Limited. Counts toward the 3+ Limited stack.'
      : grade === 'high'
        ? 'Methodology §5 Avoid.'
        : grade === 'moderate'
          ? 'Methodology §5 Caution. Does not count toward the t137u stack.'
          : 'Methodology §5 Cleared. Does not count toward the t137u stack.';
  return { name, riskLevel: grade, stackCountExempt: !counts, source: `${panel}; ${meth}`, ...(why && !why.startsWith('Methodology') ? { why } : {}) };
}

